// Vendored workflow engine: generated by scripts/sync-workflow-engine.mjs, never edited by hand. Source, commit and local patches: lib/workflow-engine/UPSTREAM.json
/**
 * init — materialize a WorkflowInstance from a WorkflowDSL for a task.
 *
 * 1. Gate on `init.condition` (mongo expr over the task; placeholder strings pass).
 * 2. Apply `init.apply.default` as a secondary filter over the task.
 * 3. Resolve each StepTemplate:
 *      due_on.$delta        → absolute ISO datetime from `now`
 *      status.default       → step.status (dormant steps wait on diff rules)
 *      state.default        → step.state (label only; see STEP_STATES)
 *      evidence_required    → default, overridden by condition.query when it matches;
 *                             condition.prompt is deferred to pending_prompts
 *      assignee.condition   → directory query (limit-capped); prompt deferred
 */
import { randomUUID } from 'node:crypto';
import {
  STEP_STATES,
  type AssigneeSpec,
  type Delta,
  type StepTemplate,
  type WorkflowDSL,
} from '../../../dsl/types.ts';
import type { Directory } from './evaluator.ts';
import { matches, substituteObject } from './mongo.ts';
import type { AttachedObject, StepState, WorkflowInstance } from './state.ts';
import { DEFAULT_ORGANIZATION_ID } from './identity.ts';

const isExpr = (v: unknown): v is Record<string, unknown> =>
  v !== null && typeof v === 'object' && !Array.isArray(v);

/**
 * Directory field marking someone as still with the organisation. Mirrors
 * the platform's `Person.employment_status_active`.
 */
export const ACTIVE_FIELD = 'employment_status_active';

/**
 * Resolve a step's assignees from its spec. Shared by init, by rework
 * re-resolution and by the departure sweep, so all three select people the
 * same way.
 *
 * `$ne: false` rather than `true`: directory records that simply do not carry
 * the field are treated as present, so adding the default cannot silently
 * empty every existing workflow's assignments.
 */
export function resolveAssignees(
  spec: AssigneeSpec,
  directory: Directory,
  exclude: string[] = [],
  balancer?: Balancer,
  key?: string,
  organizationId = DEFAULT_ORGANIZATION_ID,
  objectData: Record<string, unknown> = {},
): { ids: string[]; prompt?: string } {
  const { prompt, query } = spec.condition.$or;
  if (!query || !isExpr(query)) return { ids: [], prompt };
  const substituted = substituteObject(query, objectData);
  // A query naming object data the object does not carry resolves to nobody,
  // and says so. Matching on the remaining clauses instead would hand the step
  // to whoever merely shares the role.
  if (substituted.unresolved.length > 0) {
    return {
      ids: [],
      prompt: `assignee query references object data not present on this instance: ${substituted.unresolved.join(', ')}`,
    };
  }
  const q: Record<string, unknown> = { ...(substituted.query as Record<string, unknown>) };
  // Only supply the presence clause when the author has not written one. A
  // safety default must never *widen* an explicitly narrower filter: an author
  // asking for `true` means strictly true, and `$ne: false` also matches
  // records missing the field.
  if (spec.require_active !== false && !(ACTIVE_FIELD in q)) q[ACTIVE_FIELD] = { $ne: false };
  const candidates = directory
    .query(q, Infinity, organizationId)
    .map((u) => u.id)
    .filter((id) => !exclude.includes(id));
  const limit = spec.limit ?? 1;
  const ordered = balancer ? balancer.order(candidates, spec, key, organizationId) : candidates;
  return { ids: ordered.slice(0, limit), prompt };
}

/**
 * Orders candidates for a step. Injected rather than built in, because
 * "least loaded" is a question about every live instance and the resolver has
 * no business reaching into the store itself.
 */
export interface Balancer {
  /** `key` identifies the step template, so round_robin rotates per step. */
  order(candidates: string[], spec: AssigneeSpec, key?: string, organizationId?: string): string[];
}

export function deltaToDate(delta: Delta, from: Date): string {
  const ms =
    (delta.days ?? 0) * 86_400_000 + (delta.hours ?? 0) * 3_600_000 + (delta.minutes ?? 0) * 60_000;
  return new Date(from.getTime() + ms).toISOString();
}

export function taskMatchesInit(dsl: WorkflowDSL, task: Record<string, unknown>): boolean {
  const { condition, apply } = dsl.init;
  if (isExpr(condition) && !matches(task, condition)) return false;
  if (isExpr(apply?.default) && !matches(task, apply.default)) return false;
  return true;
}

function materializeStep(
  tpl: StepTemplate,
  task: Record<string, unknown>,
  directory: Directory,
  now: Date,
  pending: Record<string, unknown>,
  balancer?: Balancer,
  workflowId?: string,
  organizationId = DEFAULT_ORGANIZATION_ID,
): StepState {
  const step: StepState = {
    id: tpl.id,
    title: tpl.title,
    description: tpl.description,
    due_on: tpl.due_on ? deltaToDate(tpl.due_on.$delta, now) : undefined,
    status: tpl.status?.default ?? true,
    // first vocabulary entry is the default; the engine ascribes it no meaning
    state: tpl.state?.default ?? STEP_STATES[0],
    evidence_required: tpl.evidence_required?.default ?? false,
    comments_required: tpl.comments_required?.default ?? false,
    comments: [],
    evidence: [],
    // Materialized so the demand cannot be re-scoped under a live instance by a
    // later PUT /workflows/:id, and survives deletion of the step template.
    comments_required_on: tpl.comments_required?.required_on,
    comments_criterion: tpl.comments_required?.evaluation_criterion,
    evidence_required_on: tpl.evidence_required?.required_on,
    evidence_criterion: tpl.evidence_required?.evaluation_criterion,
    completed_on_delta: tpl.completed_on_delta?.default ?? 0,
    ...(tpl.state?.default === 'completed' && tpl.completed_at?.default
      ? { completed_at: tpl.completed_at.default }
      : {}),
    assignee: [],
  };

  // `condition` may only RAISE a demand. Assigning its result instead would let
  // a caller switch off a `default: true` requirement simply by omitting the
  // property from the task body they supply at attach time.
  const evCond = tpl.evidence_required?.condition?.$or;
  if (evCond?.query && isExpr(evCond.query)) {
    step.evidence_required = step.evidence_required || matches(task, evCond.query);
  } else if (evCond?.prompt) {
    pending[`steps.${tpl.id}.evidence_required`] = evCond.prompt;
  }

  const cmCond = tpl.comments_required?.condition?.$or;
  if (cmCond?.query && isExpr(cmCond.query)) {
    step.comments_required = step.comments_required || matches(task, cmCond.query);
  } else if (cmCond?.prompt) {
    pending[`steps.${tpl.id}.comments_required`] = cmCond.prompt;
  }

  const asg = tpl.assignee;
  if (asg) {
    const { ids, prompt } = resolveAssignees(
      asg,
      directory,
      [],
      balancer,
      `${organizationId}:${workflowId}:${tpl.id}`,
      organizationId,
      task,
    );
    step.assignee = ids;
    if (step.assignee.length === 0) {
      // Never leave a step silently unassignable: either defer to the prompt,
      // or record that the deterministic query matched nobody so an operator
      // can see it instead of discovering an orphaned step later.
      pending[`steps.${tpl.id}.assignee`] =
        prompt ??
        `assignee query ${JSON.stringify(asg.condition.$or.query)} matched no present directory user — assign ${tpl.id} manually`;
    }
  }

  // Seeded in the template, not added after attach: a later write can fail
  // after the instance exists, and nothing would retry it.
  const seen = new Set<string>();
  for (const entry of tpl.evidence?.default ?? []) {
    if (seen.has(entry.ref)) continue;
    seen.add(entry.ref);
    step.evidence.push({
      ref: entry.ref,
      at: entry.at ?? now.toISOString(),
      actor: entry.actor ?? step.assignee[0] ?? 'system',
    });
  }

  return step;
}

/**
 * Resolve the workflow's flat step order: declared `init.flatten_order` first
 * (ignoring unknown ids), then every remaining step in declaration order.
 */
export function flatOrder(dsl: WorkflowDSL): string[] {
  const declared = dsl.init.steps.map((s) => s.id);
  const named = (dsl.init.flatten_order ?? []).filter((id) => declared.includes(id));
  return [...named, ...declared.filter((id) => !named.includes(id))];
}

export function initInstance(
  workflowId: string,
  dsl: WorkflowDSL,
  task: Record<string, unknown>,
  directory: Directory,
  now = new Date(),
  actor?: string,
  balancer?: Balancer,
  organizationId = DEFAULT_ORGANIZATION_ID,
  object?: Omit<AttachedObject, 'data'>,
  definitionVersion = 1,
): WorkflowInstance {
  if (!taskMatchesInit(dsl, task)) {
    throw new Error('task does not satisfy init.condition / init.apply.default');
  }
  const pending: Record<string, string> = {};
  const steps = dsl.init.steps.map((tpl) =>
    materializeStep(tpl, task, directory, now, pending, balancer, workflowId, organizationId),
  );
  const at = now.toISOString();
  return {
    id: randomUUID(),
    organization_id: organizationId,
    workflow_id: workflowId,
    definition_version: definitionVersion,
    revision: 0,
    object: {
      type: object?.type ?? 'task',
      id: object?.id ?? randomUUID(),
      data: task,
    },
    task,
    start_id: dsl.init.start_id,
    steps,
    outbox: [],
    pending_prompts: pending,
    flat_order: flatOrder(dsl),
    history: [{ at, type: 'instance_created', actor, source: 'user' }],
    created_at: at,
    updated_at: at,
  };
}
